class Solution {
public:
    int largestVariance(std::string s) {
        std::vector<int> freq(26, 0);
        for (char c : s) freq[c - 'a']++;
        int ans = 0;
        for (int i = 0; i < 26; ++i) {
            if (freq[i] == 0) continue;
            for (int j = 0; j < 26; ++j) {
                if (i == j || freq[j] == 0) continue;
                char a = 'a' + i, b = 'a' + j;
                int cnt_a = 0, cnt_b = 0;
                bool has_b = false;
                for (char ch : s) {
                    if (ch == a) cnt_a++;
                    else if (ch == b) cnt_b++;
                    if (cnt_b > 0) ans = std::max(ans, cnt_a - cnt_b);
                    else if (has_b) ans = std::max(ans, cnt_a - 1);
                    if (cnt_b > cnt_a) {
                        cnt_a = 0;
                        cnt_b = 0;
                        has_b = true;
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int largestVariance(String s) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) freq[c - 'a']++;
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) continue;
            for (int j = 0; j < 26; j++) {
                if (i == j || freq[j] == 0) continue;
                char a = (char) ('a' + i), b = (char) ('a' + j);
                int cntA = 0, cntB = 0;
                boolean hasB = false;
                for (int k = 0; k < s.length(); k++) {
                    char ch = s.charAt(k);
                    if (ch == a) cntA++;
                    else if (ch == b) cntB++;
                    if (cntB > 0) ans = Math.max(ans, cntA - cntB);
                    else if (hasB) ans = Math.max(ans, cntA - 1);
                    if (cntB > cntA) {
                        cntA = 0;
                        cntB = 0;
                        hasB = true;
                    }
                }
            }
        }
        return ans;
    }
}

